import{_ as e,p as a,q as n,Y as r}from"./framework-e1bed10d.js";const t={},i=r('<h1 id="内部类" tabindex="-1"><a class="header-anchor" href="#内部类" aria-hidden="true">#</a> 内部类</h1><p>当一个类中，对事物的描述过于复杂时，可以使用内部类，内部类是对事物一部分的描述，内部氛围成员内部类、静态内部类、局部内部类</p><h2 id="成员内部类" tabindex="-1"><a class="header-anchor" href="#成员内部类" aria-hidden="true">#</a> 成员内部类</h2><p>在类的内部定义，不使用static修饰</p><p>定义方式：一般不可以定义静态成员，除非同时使用static和final进行修饰</p><p>访问权限：成员内部类可以访问外部类的所有成员变量和方法</p><p>被访问权限：在实例方法中访问，可以直接使用new Inner()的方式，外部类的静态方法和外部类的外部，需要使用new Outer().new Inner()</p><h2 id="静态内部类" tabindex="-1"><a class="header-anchor" href="#静态内部类" aria-hidden="true">#</a> 静态内部类</h2><p>在类的内部定义，使用static修饰</p><p>访问权限：可以直接访问外部类的静态变量和静态方法，要访问外部类的实例变量和实例方式需要使用new Outer()的方式</p><p>被访问权限：外部类的静态变量和静态方法以及外部类以外的类，需要通过完整的路径访问，即Outer.Inner.method()</p><h2 id="局部内部类" tabindex="-1"><a class="header-anchor" href="#局部内部类" aria-hidden="true">#</a> 局部内部类</h2><p>在方法的内部定义，不能定义静态成员，不能定义静态方法，不能使用static进行修饰</p>',13),h=[i];function s(c,d){return a(),n("div",null,h)}const o=e(t,[["render",s],["__file","inner-class.html.vue"]]);export{o as default};
